from decimal import Decimal


def format_balance(amount: Decimal, symbol: str = "$") -> str:
    return f"{symbol}{amount:,.2f}"


def statement(lines: list[tuple[str, Decimal]]) -> str:
    width = max((len(name) for name, _ in lines), default=0)
    return "\n".join(f"{name:<{width}}  {format_balance(value)}" for name, value in lines)

from decimal import ROUND_DOWN, Decimal

CENT = Decimal("0.01")


def to_cents(amount: Decimal) -> int:
    return int((amount / CENT).to_integral_value())


def split(amount: Decimal, parts: int) -> list[Decimal]:
    if parts < 1:
        raise ValueError("parts must be at least 1")
    share = (amount / parts).quantize(CENT, rounding=ROUND_DOWN)
    return [share] * parts
